import{_ as a,o as r,c as t,a2 as n}from"./chunks/framework.BfI5QxtK.js";const m=JSON.parse('{"title":"Frame renderer architecture","description":"","frontmatter":{},"headers":[],"relativePath":"window-frame-renderers.md","filePath":"window-frame-renderers.md"}'),o={name:"window-frame-renderers.md"};function i(s,e,d,l,c,p){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="frame-renderer-architecture" tabindex="-1">Frame renderer architecture <a class="header-anchor" href="#frame-renderer-architecture" aria-label="Permalink to &quot;Frame renderer architecture&quot;">​</a></h1><p>Gnoblin owns decoration policy, geometry and input. An external process draws the frame. The private v1 protocol is experimental.</p><p>For configuration, see <a href="/gnoblin/guides/window_frames">titlebars</a>. For implementation steps, see <a href="./frame-renderer-api">write a renderer</a>.</p><h2 id="ownership" tabindex="-1">Ownership <a class="header-anchor" href="#ownership" aria-label="Permalink to &quot;Ownership&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gnoblin</th><th>Renderer</th></tr></thead><tbody><tr><td>Decoration negotiation</td><td>Frame appearance</td></tr><tr><td>Crop and committed extents</td><td>Buffers and damage</td></tr><tr><td>Move/resize grabs and actions</td><td>Button hit regions</td></tr><tr><td>Content exclusion and final mask</td><td>Hover/pressed appearance</td></tr><tr><td>Native fallback</td><td>Theme interpretation</td></tr></tbody></table><p>One process can render many frames. Gnoblin passes it a private Wayland connection; only that connection sees the frame global. This limits protocol capabilities, not the executable&#39;s OS access.</p><h2 id="commit-sequence" tabindex="-1">Commit sequence <a class="header-anchor" href="#commit-sequence" aria-label="Permalink to &quot;Commit sequence&quot;">​</a></h2><ol><li>Gnoblin creates a frame handle with identity, state, actions and geometry.</li><li>The renderer attaches a surface with no existing role.</li><li>It acknowledges configure, declares regions and commits matching pixels.</li><li>Gnoblin applies the acknowledged state atomically.</li></ol><p>Regions are double-buffered, limited to 64 and last-defined-wins. A toolkit xdg-toplevel cannot take a second role.</p><p>The compositor excludes the app body from painting and input. Native resize regions take priority. The renderer never takes keyboard focus or requests arbitrary commands.</p><p>See the <a href="https://github.com/kierandrewett/gnoblin/blob/main/src/protocols/window-frame/gnoblin-window-frame-v1.xml" target="_blank" rel="noreferrer">protocol XML</a>.</p><h2 id="slow-or-failed-renderers" tabindex="-1">Slow or failed renderers <a class="header-anchor" href="#slow-or-failed-renderers" aria-label="Permalink to &quot;Slow or failed renderers&quot;">​</a></h2><p>App commits never wait for a renderer. Geometry changes use native fallback until a matching buffer arrives; stale generations cannot replace newer layout.</p><p>Invalid dimensions or serials disconnect the renderer. Process failure triggers bounded backoff, with at most four launch attempts per session. Shutdown terminates only Gnoblin&#39;s renderer children.</p><p>A stalled renderer may keep valid current pixels; native controls remain usable. New geometry selects fallback. There is no continuous heartbeat.</p><p>The helper permits two outstanding shared-memory buffers per frame. Its full-window canvases need further high-DPI and many-window cost measurements.</p><h2 id="reference-adapters" tabindex="-1">Reference adapters <a class="header-anchor" href="#reference-adapters" aria-label="Permalink to &quot;Reference adapters&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/build-frame-renderers.sh</span></span></code></pre></div><p>Outputs:</p><ul><li><code>build/frame-renderers/gnoblin-frame-cairo</code></li><li><code>build/frame-renderers/gnoblin-frame-qt</code></li></ul><p>Both accept <code>--theme-file=/absolute/path</code> containing a six-digit hex background. Valid edits repaint; invalid edits retain the previous colour.</p><p>Their button layout is fixed. Native fallback separately supports Lua&#39;s <code>button_layout</code>. Other toolkits need an adapter; ordinary toolkit windows cannot be attached directly.</p><h2 id="reload-and-tests" tabindex="-1">Reload and tests <a class="header-anchor" href="#reload-and-tests" aria-label="Permalink to &quot;Reload and tests&quot;">​</a></h2><p><code>gnoblinctl config reload</code> restarts configured services, even when an executable&#39;s path is unchanged. Compositor upgrades require a new session.</p><p>Private tests cover pixels, crop, controls, fullscreen, theme reload and fallback. Start with <code>tests/test-window-frames.py</code>; use <code>GNOBLIN_SSD_RENDERER=cairo</code> or <code>qt</code> for adapters.</p><p>Mixed-scale transitions, popup-heavy cropped apps, adversarial fuzzing and GPU-buffer adapters need further coverage.</p>',26)])])}const u=a(o,[["render",i]]);export{m as __pageData,u as default};
